const policies = [
  ["Returns", "Return window", "Items can be returned within 7 days of delivery if unused and in original packaging."],
  ["Returns", "Non-returnable items", "Screen protectors, opened earphones, and items without original packaging cannot be returned."],
  ["Returns", "Refund time", "Refunds are processed within 5 to 7 working days after the returned item is received and checked."],
  ["Returns", "Damaged or wrong item", "If you receive a damaged or wrong item, contact support within 48 hours of delivery with photos. We replace or refund."],
  ["Shipping", "Delivery time", "Major cities: 2 to 4 working days. Other cities: 4 to 7 working days."],
  ["Shipping", "Delivery charges", "Flat Rs. 200 delivery charge. Free delivery on orders above Rs. 5,000."],
  ["Shipping", "Order tracking", "A tracking ID is shared by SMS once the order is shipped."],
  ["Payments", "Payment methods", "Cash on delivery, bank transfer, and card payments are accepted."],
  ["Payments", "Payment safety", "Support will never ask for your card number, PIN, password, or OTP."],
  ["Cancellation", "Cancel an order", "Orders can be cancelled before they are shipped. Once shipped, use the return process instead."],
  ["Warranty", "Warranty claims", "Warranty covers manufacturing defects only. It does not cover physical damage or water damage."],
  ["Support", "Support hours", "Support team is available Monday to Saturday, 10 AM to 8 PM (Pakistan time)."],
  ["Support", "Human agent", "Customers can ask for a human agent at any time. Complaints and refund disputes are handled by the support team."]
];

return policies.map(([category, topic, policy]) => ({
  json: {
    text: topic + ": " + policy,
    category: category,
    topic: topic
  }
}));
